import React, { useState } from 'react';
import '../styles/Contacto.css';

const Contacto = () => {
  const [form, setForm] = useState({ nombre: '', email: '', mensaje: '' });
  const [enviado, setEnviado] = useState(false);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    await fetch('http://localhost:4000/api/contacto', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form)
    });
    setEnviado(true);
  };

  return (
    <div className="contacto-container">
      <h2 className="contacto-title">Contacto</h2>
      {enviado ? <p className="contacto-msg">¡Gracias por contactarnos! Pronto te responderemos.</p> : (
        <form className="contacto-form" onSubmit={handleSubmit}>
          <input name="nombre" placeholder="Nombre" value={form.nombre} onChange={handleChange} required />
          <input name="email" type="email" placeholder="Email" value={form.email} onChange={handleChange} required />
          <textarea name="mensaje" placeholder="Mensaje" value={form.mensaje} onChange={handleChange} required />
          <button type="submit">Enviar</button>
        </form>
      )}
    </div>
  );
};

export default Contacto;
